// Extraer datos del payload de Zernio
const body = $input.first().json.body || $input.first().json;

const senderPhone = body.sender?.phone || body.from || body.phone || 'Unknown';
const senderName = body.sender?.name || body.name || 'Cliente';
const messageText = body.message?.text || body.text || body.content || '';
const tenantId = body.tenant_id || body.metadata?.tenant_id || 'default-tenant';

return [{
  json: {
    senderPhone,
    senderName,
    messageText,
    tenantId,
    rawPayload: body
  }
}];

// Consulta catálogo en Supabase vía HTTP
