// Consulta disponibilidad de citas en la base de datos
const { fecha, estilista } = $fromAI;
return JSON.stringify({
  fecha: fecha || 'hoy',
  estilista: estilista || 'Cualquiera disponible',
  horarios_libres: ['10:00 AM', '11:30 AM', '03:00 PM', '04:30 PM', '06:00 PM']
});

const { servicio, estilista, fecha_hora, nombre_cliente, telefono } = $fromAI;
return JSON.stringify({
  status: 'SUCCESS',
  cita_id: 'app-' + Math.random().toString(36).substring(2, 9),
  mensaje: 'Cita agendada y confirmada exitosamente',
  resumen: {
    servicio,
    estilista,
    fecha_hora,
    cliente: nombre_cliente,
    telefono
  }
});
